Revise the ConcIR candidate for the same requirements. The requirements and the frozen contract are authoritative; the feedback is repair context.

<domain_requirements>
A worker starts a nested group of two tasks; the two inner tasks both need mutexes A and B and must not form a circular wait. Every interleaving must terminate and the outer worker must complete. On completion the program must print exactly one line `DONE done=1` and then exit; it must terminate.
</domain_requirements>

<contract>
{
  "name": "nested-scope",
  "properties": [
    {
      "kind": "deadlock_free",
      "id": "no-deadlock"
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::outer completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::outer"
      }
    },
    {
      "kind": "reachable",
      "description": "main::x1 holds [a, b] at once",
      "goal": {
        "kind": "holds_all",
        "function": "main::x1",
        "resources": [
          "main::a",
          "main::b"
        ]
      }
    },
    {
      "kind": "reachable",
      "description": "main::x2 holds [a, b] at once",
      "goal": {
        "kind": "holds_all",
        "function": "main::x2",
        "resources": [
          "main::a",
          "main::b"
        ]
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

